    ((PathAttachmentSample *)((char *)primary_samples + lead_offset))[0].center_x = (float)width_cells * 0.5f - 4.0f;
    ((PathAttachmentSample *)((char *)primary_samples + lead_offset))[0].rotation_scalar_98 = 0.0f;
    ((PathAttachmentSample *)((char *)primary_samples + lead_offset))[0].rotation_scalar_94 = 0.0f;
    ((PathAttachmentSample *)((char *)primary_samples + lead_offset))[0].special_scalar = 0.0f;
    ((PathAttachmentSample *)((char *)primary_samples + lead_offset))[0].lateral_scale = 1.0f;
    ((PathAttachmentSample *)((char *)primary_samples + lead_offset))[0].transform.Identity();
    float z;
    initialize_primary_position(primary_samples, lead_offset, i, false, 0.0f, 0.0f, 0.0f, z);
    ((PathAttachmentSample *)((char *)secondary_samples + lead_offset))[0].transform.Identity();
    ((PathAttachmentSample *)((char *)secondary_samples + lead_offset))[0].transform.position.x = ((PathAttachmentSample *)((char *)primary_samples + lead_offset))[0].center_x;
    ((PathAttachmentSample *)((char *)secondary_samples + lead_offset))[0].transform.position.y = 0.49000001f;
    ((PathAttachmentSample *)((char *)secondary_samples + lead_offset))[0].transform.position.z = z;
    ++i;
    lead_offset += sizeof(PathAttachmentSample);
} while (lead_offset < 7 * (int)sizeof(PathAttachmentSample));

((PathAttachmentSample *)((char *)primary_samples + departure_offset))[0].transform.position.x = ((PathAttachmentSample *)((char *)primary_samples + departure_offset))[0].center_x;
((PathAttachmentSample *)((char *)primary_samples + departure_offset))[0].transform.position.y = 0.0f;
((PathAttachmentSample *)((char *)primary_samples + departure_offset))[0].transform.position.z = z;
((PathAttachmentSample *)((char *)secondary_samples + departure_offset))[0].transform.Identity();
((PathAttachmentSample *)((char *)secondary_samples + departure_offset))[0].transform.position.x = ((PathAttachmentSample *)((char *)primary_samples + departure_offset))[0].center_x;
((PathAttachmentSample *)((char *)secondary_samples + departure_offset))[0].transform.position.y = 0.49000001f;
((PathAttachmentSample *)((char *)secondary_samples + departure_offset))[0].transform.position.z = z;
departure_offset += sizeof(PathAttachmentSample);

    path->strip_mesh->RequestVertices((path->width_cells + 1) *
                                      (path->segment_count + 1));
    path->strip_mesh->RequestFaceQuads(2 * path->width_cells * path->segment_count);

    Vector3 *vertices = path->strip_mesh->vertices;
    cRFaceQuad *facequads = path->strip_mesh->facequads;
    int row = 0;
    int column;
    int face_index;
    if (path->segment_count >= 0)
    {
        int sample_offset = 0;
        do
        {
            column = 0;
            if (path->width_cells >= 0)
            {
                do
                {
                    if (row != path->segment_count)
                    {
                        float lateral = (float)column - (float)path->width_cells * 0.5f;
                        Vector3 lateral_offset =
                            ((PathAttachmentSample *)((char *)path->primary_samples +
                                                    sample_offset))
                                ->transform.basis_right *
                            lateral;
                        Vector3 generated_position =
                            ((PathAttachmentSample *)((char *)path->primary_samples +
                                                    sample_offset))
                                ->transform.position +
                            lateral_offset;
                        Vector3 *vertex =
                            &vertices[column + row * (path->width_cells + 1)];
                        *vertex = generated_position;
                    }
                    else
                    {
                        float lateral = (float)column - (float)path->width_cells * 0.5f;
                        Vector3 generated_position =
                            (((PathAttachmentSample *)((char *)path->primary_samples +
                                                     sample_offset))[-1]
                                 .transform.position +
                             Vector3(0.0f, 0.0f, 1.0f)) +
                            (((PathAttachmentSample *)((char *)path->primary_samples +
                                                     sample_offset))[-1]
                                 .transform.basis_right *
                             lateral);
                        Vector3 *vertex =
                            &vertices[column + row * (path->width_cells + 1)];
                        *vertex = generated_position;
                    }
                    ++column;
                } while (column <= path->width_cells);
            }
            ++row;
            sample_offset += sizeof(PathAttachmentSample);
        } while (row <= path->segment_count);
    }

    for (row = 0; row < path->segment_count; ++row)
    {
        column = 0;
        if (path->width_cells > 0)
        {
            float v0 = (float)(row % 8) * 0.125f;
            float v1 = (float)(row % 8 + 1) * 0.125f;
            do
            {
                float u0 = (float)column * 0.125f;
                float u1 = (float)(column + 1) * 0.125f;

                for (face_index = 0; face_index < 2; ++face_index)
                {
                    int face_offset =
                        2 * column + 2 * row * path->width_cells + face_index;

                    if (face_index == 0)
                    {
                        facequads[face_offset].header_word = 0;
                        facequads[face_offset].vertex_0 =
                            column + row * ((unsigned short)path->width_cells + 1);
                        facequads[face_offset].vertex_1 =
                            row * ((unsigned short)path->width_cells + 1) + column + 1;
                        facequads[face_offset].vertex_2 =
                            (row + 1) * ((unsigned short)path->width_cells + 1) +
                            column + 1;
                        facequads[face_offset].vertex_3 =
                            column +
                            (row + 1) * ((unsigned short)path->width_cells + 1);
                        if (((column ^ row) & 1) == 0)
                        {
                            facequads[face_offset].texture_ref =
                                g_texture_refs.Add(texture_a, 0, 0);
                        }
                        else
                        {
                            facequads[face_offset].texture_ref =
                                g_texture_refs.Add(texture_a, 0, 0);
                        }
                    }
                    else
                    {
                        facequads[face_offset].header_word = 0;
                        facequads[face_offset].vertex_0 =
                            row * ((unsigned short)path->width_cells + 1) + column + 1;
                        facequads[face_offset].vertex_1 =
                            column + row * ((unsigned short)path->width_cells + 1);
                        facequads[face_offset].vertex_2 =
                            column +
                            (row + 1) * ((unsigned short)path->width_cells + 1);
                        facequads[face_offset].vertex_3 =
                            (row + 1) * ((unsigned short)path->width_cells + 1) +
                            column + 1;
                        if (((column ^ row) & 1) == 0)
                        {
                            facequads[face_offset].texture_ref =
                                g_texture_refs.Add(texture_b, 0, 0);
                        }
                        else
                        {
                            facequads[face_offset].texture_ref =
                                g_texture_refs.Add(texture_b, 0, 0);
                        }
                    }
                    if (face_index == 0)
                    {
                        facequads[face_offset].uv[0].u = u0;
                        facequads[face_offset].uv[0].v = v0;
                        facequads[face_offset].uv[1].u = u1;
                        facequads[face_offset].uv[1].v = v0;
                        facequads[face_offset].uv[2].u = u1;
                        facequads[face_offset].uv[2].v = v1;
                        facequads[face_offset].uv[3].u = u0;
                        facequads[face_offset].uv[3].v = v1;
                    }
                    else
                    {
                        facequads[face_offset].uv[0].u = u1;
                        facequads[face_offset].uv[0].v = v0;
                        facequads[face_offset].uv[1].u = u0;
                        facequads[face_offset].uv[1].v = v0;
                        facequads[face_offset].uv[2].u = u0;
                        facequads[face_offset].uv[2].v = v1;
                        facequads[face_offset].uv[3].u = u1;
                        facequads[face_offset].uv[3].v = v1;
                    }
                }
                ++column;
            } while (column < path->width_cells);
        }
    }
}

static __forceinline float initialize_primary_position(PathAttachmentSample *&bank, int offset, int index, bool curved, float angle, float radius, float height)
{
    ((PathAttachmentSample *)((char *)bank + offset))[0].transform.position.x =
        ((PathAttachmentSample *)((char *)bank + offset))[0].center_x;
    if (curved)
        ((PathAttachmentSample *)((char *)bank + offset))[0].transform.position.y =
            (1.0f - Cos(angle)) * radius * height;
    float z = (float)index;
    if (!curved)
        ((PathAttachmentSample *)((char *)bank + offset))[0].transform.position.y = 0.0f;
    ((PathAttachmentSample *)((char *)bank + offset))[0].transform.position.z = z;
    return z;
}

static __forceinline void initialize_secondary_curve(PathAttachmentSample *&primary, PathAttachmentSample *&secondary, int offset, float angle, float radius, float height, float z)
{
            ((PathAttachmentSample *)((char *)secondary + offset))
                ->transform.Identity();
