                ->transform.position.x =
                ((PathAttachmentSample *)((char *)primary + offset))
                    ->center_x;
            ((PathAttachmentSample *)((char *)secondary + offset))
                ->transform.position.y =
                (1.0f - Cos(angle)) * radius * height + 0.49000001f;
            ((PathAttachmentSample *)((char *)secondary + offset))
                ->transform.position.z = z;
}

